/*
 * Smoke-test workload for CHAOS fault injection.
 *
 * Properties:
 *   - Deterministic, reproducible output: prints sum and CRC32 of a
 *     100k-element integer array, both computed from a fixed seed.
 *   - Short enough for gem5 O3 (a few million instructions).
 *   - Enough computation that architectural integer registers are read
 *     and written repeatedly (not pure IO).
 *
 * Build (host is aarch64, native, static for gem5 SE):
 *   gcc -static -O2 -o test_workload test_workload.c
 */
#include <stdio.h>
#include <stdint.h>

#define N 100000

/* Linear congruential generator (deterministic, no libc random state). */
static uint32_t my_rand(uint32_t *state) {
    *state = *state * 1103515245u + 12345u;
    return *state;
}

/* Standard CRC32 (poly 0xEDB88320), table-free iterative form. */
static uint32_t crc32(const uint32_t *buf, int n) {
    uint32_t crc = 0xFFFFFFFFu;
    for (int i = 0; i < n; i++) {
        uint32_t v = buf[i];
        for (int b = 0; b < 4; b++) {
            uint8_t byte = (v >> (b * 8)) & 0xFF;
            crc ^= byte;
            for (int j = 0; j < 8; j++) {
                uint32_t mask = -(crc & 1u);
                crc = (crc >> 1) ^ (0xEDB88320u & mask);
            }
        }
    }
    return ~crc;
}

int main(void) {
    static uint32_t data[N];
    uint32_t state = 0x12345678u;
    uint64_t sum = 0;

    for (int i = 0; i < N; i++) {
        data[i] = my_rand(&state);
        sum += data[i];
    }

    uint32_t c = crc32(data, N);

    /* Deterministic, single-line output for easy diff against golden. */
    printf("SUM=%llu CRC=%08x\n", (unsigned long long)sum, c);
    return 0;
}

