            return "Crash"      # SUT segfault via SE page-fault handler (legit DUE)
        return "tool-bug"       # other assert/panic = tool boundary
    # 3. Hang
    if timed_out or (wall > 3 * GOLDEN_WALL and wl == ""):
        return "Hang"
    # 4. Inactive
    if nfi == 0:
        return "Inactive"
    # 5. Crash: no stdout, fast exit (covers non-panic crash paths)
    if wl == "":
        return "Crash"
    # 6. Masked / SDC
    if wl == golden_stdout:
        return "Masked"
    return "SDC"

