struct PhysRegId {
    int idx; int cls;
    PhysRegId(int i=0, int c=0): idx(i), cls(c) {}
    int index() const { return idx; }
    int classValue() const { return cls; }
};
using PhysRegIdPtr = PhysRegId*;
}}

using namespace gem5::o3;

// Copied structure of SimpleFreeList (simplified)
class SimpleFreeList {
    std::queue<PhysRegIdPtr> freeRegs;
public:
    void addReg(PhysRegIdPtr r) { freeRegs.push(r); }   // no dup check
    PhysRegIdPtr getReg() { assert(!freeRegs.empty()); auto r=freeRegs.front(); freeRegs.pop(); return r; }
    bool contains(PhysRegIdPtr r) const {
        // hack: std::queue container access
        struct Q : std::queue<PhysRegIdPtr> { using std::queue<PhysRegIdPtr>::c; };
        for (auto &x : static_cast<const Q&>(freeRegs).c) if (x==r) return true;
        return false;
    }
    size_t size() const { return freeRegs.size(); }
};

int main() {
    PhysRegId regA(5, 0);   // "physical register 5"
    PhysRegId regB(6, 0);
    SimpleFreeList fl;
    fl.addReg(&regA);
    fl.addReg(&regB);
    printf("init: size=%zu\n", fl.size());

    // Scenario 1: double-release the same phys
    fl.addReg(&regA);   // regA already... wait it was already gotten? simulate: A in list twice
    printf("after double-add A: size=%zu (duplicate allowed, no assert)\n", fl.size());
    printf("  contains A: %d (A appears twice in queue)\n", fl.contains(&regA) ? 1:0);

    // Scenario 2: getReg twice when only 1 unique but listed twice
    PhysRegIdPtr g1 = fl.getReg();
    PhysRegIdPtr g2 = fl.getReg();
    PhysRegIdPtr g3 = fl.getReg();
    printf("g1=%p g2=%p g3=%p\n", (void*)g1,(void*)g2,(void*)g3);
    printf("g1==A: %d, g2==A: %d (same phys handed out twice!)\n", g1==&regA, g2==&regA);
    return 0;
}
