          idx_out_of_range(false),
          corrupted_entry_lifetime(-1),
          attackEvent([this] { this->doInjectA(); }, name(), false,
                      /*Priority*/ 60),  // > CPU_Tick_Pri(50): fire after rename stage
          rng_seed_value(0),  // placeholder, set below
          stats(nullptr)
    {
        if (!cpu) {
            throw std::runtime_error(
                "CHAOSRAT: cpu is not an O3CPU. CHAOSRAT only supports O3CPU "
                "(needs regFile/renameMap/freeList).");
        }
        if (target_arch_reg < 0 || target_arch_reg > 30) {
            throw std::runtime_error("CHAOSRAT: target_arch_reg must be 0-30 (X0-X30).");
        }
        if (max_faults > 0 || kind == Kind::RatEntry) {
            log_stream = simout.create("fault_injections.log", false, true);
            if (!log_stream || !log_stream->stream())
                panic("CHAOSRAT: Could not open log file");
            stats = std::make_unique<CHAOSRATStats>(this);
            rng.seed(rng_seed != 0 ? rng_seed : rd());
            // A: schedule the inject event at firstClock (high priority after rename).
            // B: just mark pending; the renameDestRegs hook will fire it.
            if (kind == Kind::RatEntry) {
                if (!attackEvent.scheduled())
                    schedule(attackEvent, cpu->clockEdge(first_clock));
            } else {
                b_pending = false;  // will arm at firstClock via a separate tick
                // Arm B at firstClock: schedule a lightweight event that just sets b_pending=true.
                // (Reuse attackEvent's slot but with a different action is messy; instead we
                //  check first_clock against curCycle inside hookRenameDest. Simpler: arm now
                //  but only allow firing after firstClock.)
                b_pending = true;  // armed; hookRenameDest checks curCycle >= first_clock
            }
        }
    }

    CHAOSRAT::CHAOSRATStats::CHAOSRATStats(statistics::Group *parent)
        : statistics::Group(parent),
          ADD_STAT(numFaultsInjected, statistics::units::Count::get(),
                   "Total number of faults injected")
    {}

    CHAOSRAT::~CHAOSRAT() {}

    // Query who owns a phys idx right now: walk frontend renameMap for IntRegClass,
    // return arch reg index (or -1 if none); also say if it's in the free list.
    int
    CHAOSRAT::queryOwner(int phys_idx, bool &in_freelist)
    {
        in_freelist = false;
        // free list check
        o3::PhysRegIdPtr phys_ptr = cpu->physRegFile().intPhysRegId(phys_idx);
        in_freelist = cpu->physFreeList().isFree(gem5::IntRegClass, phys_ptr);
        if (in_freelist) return -1;
        // walk frontend renameMap for an owner
        gem5::ThreadContext *tc = cpu->getContext(0);
        if (!tc) return -1;
        gem5::BaseISA *isa = tc->getIsaPtr();
        if (!isa) return -1;
        const auto &rc = isa->regClasses();
        const gem5::RegClass *ic = rc[gem5::IntRegClass];
        int na = ic ? ic->numRegs() : 0;
        int cap = na < 31 ? na : 31;
        for (int a = 0; a < cap; a++) {
            gem5::RegId ar(*ic, a);
            const gem5::RegId flat = ar.flatten(*isa);
            o3::PhysRegIdPtr pm = cpu->frontRenameMap()[0].lookup(flat);
            if (pm && (int)pm->index() == phys_idx) return a;
        }
        return -1;  // allocated but no current rename-map entry (superseded, in-flight reader)
    }

    void
    CHAOSRAT::doInjectA()
    {
        // Inject A: corrupt the frontend renameMap entry for target_arch_reg.
        // 1. look up current mapping (orig phys idx)
        // 2. bit-flip the INDEX (never the pointer)
        // 3. bounds-check → OutOfRange if out (record, skip, do NOT inject)
        // 4. setEntry(archReg, &intRegIds[corrupted_idx])  — legal same-class ptr
        actual_inject_cycle = cpu->curCycle();

        gem5::ThreadContext *tc = cpu->getContext(0);
        if (!tc) { return; }
        gem5::BaseISA *isa = tc->getIsaPtr();
        if (!isa) { return; }
        const auto &rc = isa->regClasses();
        const gem5::RegClass *ic = rc[gem5::IntRegClass];
        if (!ic || ic->numRegs() == 0) return;
        if (target_arch_reg >= ic->numRegs()) return;

        gem5::RegId arch_reg(*ic, target_arch_reg);
        const gem5::RegId flat = arch_reg.flatten(*isa);

        o3::PhysRegIdPtr orig_ptr = cpu->frontRenameMap()[0].lookup(flat);
        if (!orig_ptr) return;
        orig_phys_idx = orig_ptr->index();

        int n = cpu->physRegFile().numIntPhysRegs();
        // determine corrupted index
        if (target_phys_idx_override >= 0) {
            corrupted_phys_idx = target_phys_idx_override;
            // (still record a nominal flipped_bit for the log; not meaningful for directed)
            if (flipped_bit < 0) flipped_bit = 0;
        } else {
            if (flipped_bit < 0)
                flipped_bit = std::uniform_int_distribution<int>(0, 6)(rng); // 0..6 (125<128)
            corrupted_phys_idx = orig_phys_idx ^ (1 << flipped_bit);
        }

        idx_out_of_range = (corrupted_phys_idx < 0 || corrupted_phys_idx >= n);
        if (idx_out_of_range) {
            // record and skip — do NOT inject (gem5 would crash on bad index)
            if (write_log) {
                *(log_stream->stream())
                    << "Cycle: " << cpu->curCycle()
                    << ", Kind: rat_entry"
                    << ", ArchReg[" << target_arch_reg << "]"
                    << ", OrigPhys[" << orig_phys_idx << "]"
                    << ", CorruptedPhys[" << corrupted_phys_idx << "]"
                    << ", FlippedBit: " << flipped_bit
                    << ", OutOfRange: 1 (skipped, not injected)"
                    << std::endl;
            }
            return;  // not a fault; num_faults_injected stays 0 → Inactive/OutOfRange bucket
        }

        o3::PhysRegIdPtr corrupted_ptr = cpu->physRegFile().intPhysRegId(corrupted_phys_idx);

        // setEntry on FRONTEND renameMap (class assert satisfied: intRegIds are IntRegClass)
        cpu->frontRenameMap()[0].setEntry(flat, corrupted_ptr);

        stats->numFaultsInjected++;
        ++faults_injected_count;

        // victim (who owns corrupted_phys_idx right now, AFTER our setEntry)
        bool victim_in_fl = false;
        int victim_arch = queryOwner(corrupted_phys_idx, victim_in_fl);

        if (write_log) {
            *(log_stream->stream())
                << "Cycle: " << cpu->curCycle()
                << ", Kind: rat_entry"
                << ", ArchReg[" << target_arch_reg << "]"
                << ", OrigPhys[" << orig_phys_idx << "]"
                << ", CorruptedPhys[" << corrupted_phys_idx << "]"
                << ", FlippedBit: " << flipped_bit
                << ", OutOfRange: 0"
                << ", VictimArch[" << victim_arch << "]"
                << ", VictimInFreeList: " << (victim_in_fl ? 1 : 0)
                << ", RequestedCycle: " << requested_inject_cycle
                << ", ActualCycle: " << actual_inject_cycle
                << std::endl;
        }
        // single-injection: do not reschedule (maxFaults=1 enforced by not scheduling)
    }

    bool
    CHAOSRAT::hookRenameDest(const RegId &flat_dest_regid, PhysRegIdPtr &renamed_first)
    {
        // B placeholder — to be implemented after commit.cc:1264 propagation review.
        // Returns false (never fires). B work is blocked pending user confirmation.
        return false;
    }

} // namespace gem5

