        # rename_map class assert, etc.) — not SUT faults.cc
        return "tool-bug"
    if to or rec.get("wall_time", 0) > 3 * gwall:
        return "Hang"
    if rec.get("num_faults_injected", 0) == 0:
        return "Inactive"
    wl = rec.get("stdout", "")
    if wl == "":
        return "Crash"
    if wl == golden:
        return "Masked"
    return "SDC"

