bool
CHAOSRAT::hookRenameDest(const RegId &flat_dest_regid, PhysRegIdPtr &renamed_first)
{
    // B (dest_tag): corrupt the dest tag handed to the instruction, NOT the table.
    // Wait for target_arch_reg to be a dest of a renamed instruction (after firstClock).
    if (kind != Kind::DestTag) return false;
    if (b_fired) return false;
    if (!b_pending) return false;
    if (cpu->curCycle() < first_clock) return false;

    // match: this dest reg must be the target arch reg (same class + index)
    if (flat_dest_regid.classValue() != gem5::IntRegClass) return false;
    if ((int)flat_dest_regid.index() != target_arch_reg) return false;

    // Fire: bit-flip the INDEX of the allocated dest tag (renamed_first),
    // take a legal same-class ptr from intRegIds.
    actual_inject_cycle = cpu->curCycle();
    orig_phys_idx = renamed_first->index();
    int n = cpu->physRegFile().numIntPhysRegs();
    if (target_phys_idx_override >= 0) {
        corrupted_phys_idx = target_phys_idx_override;
        if (flipped_bit < 0) flipped_bit = 0;
    } else {
        if (flipped_bit < 0)
            flipped_bit = std::uniform_int_distribution<int>(0, 6)(rng);
        corrupted_phys_idx = orig_phys_idx ^ (1 << flipped_bit);
    }
    idx_out_of_range = (corrupted_phys_idx < 0 || corrupted_phys_idx >= n);
    if (idx_out_of_range) {
        if (write_log) {
            *(log_stream->stream())
                << "Cycle: " << cpu->curCycle()
                << ", Kind: dest_tag"
                << ", ArchReg[" << target_arch_reg << "]"
                << ", OrigPhys[" << orig_phys_idx << "]"
                << ", CorruptedPhys[" << corrupted_phys_idx << "]"
                << ", FlippedBit: " << flipped_bit
                << ", OutOfRange: 1 (skipped)"
                << ", RequestedCycle: " << requested_inject_cycle
                << ", ActualCycle: " << actual_inject_cycle
                << std::endl;
        }
        b_fired = true;  // fired (but skipped); don't fire again
        return true;
    }

    // victim (who owns corrupted_phys_idx right now)
    bool victim_in_fl = false;
    int victim_arch = queryOwner(corrupted_phys_idx, victim_in_fl);

    // corrupt the dest tag handed to the inst
    PhysRegIdPtr corrupted_ptr = cpu->physRegFile().intPhysRegId(corrupted_phys_idx);
    renamed_first = corrupted_ptr;

    stats->numFaultsInjected++;
    ++faults_injected_count;
    b_fired = true;

    // start readTrace (poll for b_degraded_to_a: does table become corrupted after commit?)
    if (!readTraceEvent.scheduled())
        schedule(readTraceEvent, cpu->clockEdge(Cycles(100000)));

    if (write_log) {
        *(log_stream->stream())
            << "Cycle: " << cpu->curCycle()
            << ", Kind: dest_tag"
            << ", ArchReg[" << target_arch_reg << "]"
            << ", OrigPhys[" << orig_phys_idx << "]"
            << ", CorruptedPhys[" << corrupted_phys_idx << "]"
            << ", FlippedBit: " << flipped_bit
            << ", OutOfRange: 0"
            << ", VictimArch[" << victim_arch << "]"
            << ", VictimInFreeList: " << (victim_in_fl ? 1 : 0)
            << ", RequestedCycle: " << requested_inject_cycle
            << ", ActualCycle: " << actual_inject_cycle
            << std::endl;
    }
    return true;
}

